/**
 * The player's profile: name, avatar and guild membership.
 *
 * The account id (`playerID`) is deliberately not returned: it identifies the account to the
 * game's servers, and nothing a tool computes from a save needs it.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    readProfileFromSaveRoot
 * depends    src/save/access/values, src/save/profile/types
 * used by    src/save/profile/index
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import { coerceSaveNumber } from '../access/values'
import type { ProfileSaveExtract } from './types'

const PROFILE_KEYS = ['userName', 'avatarId', 'inGuild', 'lastGuildSeason'] as const

/** Profile fields, or null for a save that has none of them. */
export function readProfileFromSaveRoot(root: Record<string, unknown> | null): ProfileSaveExtract | null {
  if (!root || !PROFILE_KEYS.some(key => key in root)) return null
  const warnings: string[] = []
  const userName = typeof root.userName === 'string' && root.userName.trim() ? root.userName : null
  if ('inGuild' in root && typeof root.inGuild !== 'boolean') warnings.push('inGuild is not a true/false value.')
  return {
    userName,
    avatarId: coerceSaveNumber(root.avatarId),
    inGuild: typeof root.inGuild === 'boolean' ? root.inGuild : null,
    lastGuildSeason: coerceSaveNumber(root.lastGuildSeason),
    warnings,
  }
}
